const setBestOverloadMarkup=b=>{if(!b)return '';const step=b.kind==='seconds'?5:1,targetVal=Math.min(3600,b.value+step),unit=b.kind==='reps'?textFor('progress.reps','повторения'):textFor('progress.seconds','секунди');return `<button type="button" class="btn btn-small" data-action="beat-set-pr" data-kind="${esc(b.kind)}" data-value="${targetVal}">★ +${step} (${targetVal} ${esc(unit)})</button>`;};
