function emptyResults(group){return `<div class="empty"><span class="emoji">⌕</span><h3>${textFor('common.noResults','Няма съвпадения')}</h3><p>${textFor('common.changeFilters','Промени филтрите или потърси с друга дума. Няма да показваме несвързани резултати.')}</p>${group?`<button class="btn btn-small" data-action="reset-filters" data-group="${group}">${textFor('common.resetFilters','Изчисти филтрите')}</button>`:''}</div>`;}
