function filteredWorkoutList(){const searchable=workouts.map(w=>{const loc=contentFor('workout',w),en=window.FORME_WORKOUT_TRANSLATIONS?.get(w.id,'en'),de=window.FORME_WORKOUT_TRANSLATIONS?.get(w.id,'de'),exNames=(w.ids||[]).map(id=>{const raw=byId(exercises,id);if(!raw)return '';const exLoc=contentFor('exercise',raw);return [raw.name,raw.nameEn,raw.nameDe,exLoc.name].filter(Boolean).join(' ');}).join(' ');return {...w,searchText:[w.name,w.tag,w.desc,loc.name,loc.tag,loc.desc,en?.name,en?.tag,de?.name,de?.tag,exNames].filter(Boolean).join(' ')};});const base=C.filterWorkouts(searchable,state.workoutFilters),byFav=state.workoutFilters.favOnly?base.filter(w=>fav('workouts',w.id)):base;if(!state.workoutFilters.doneOnly)return byFav;const doneIds=new Set((typeof journal!=='undefined'?journal?.sessions?.()||[]:[]).map(s=>s.workoutId));return byFav.filter(w=>doneIds.has(w.id));}
function staleExerciseIds(days=14){const today=new Date(),cutoff=new Date(today.getFullYear(),today.getMonth(),today.getDate()-(Number.isFinite(days)?days:14)),cutoffKey=localDateKey(cutoff);return new Set(exercises.filter(ex=>{const last=lastSetFor(ex.id);return !last||last.date<cutoffKey;}).map(ex=>ex.id));}
function filteredExerciseList(){const base=C.filterExercises(exercises.map(ex=>contentFor('exercise',{...ex,searchText:ex.name})),state.exerciseFilters,language),byFav=state.exerciseFilters.favOnly?base.filter(ex=>fav('exercises',ex.id)):base,byPr=state.exerciseFilters.prOnly?byFav.filter(ex=>!!bestSetFor(ex.id)):byFav;if(!state.exerciseFilters.staleOnly)return byPr;const stale=staleExerciseIds(14);return byPr.filter(ex=>stale.has(ex.id));}
