function excStaleCount(){return exercises.filter(ex=>{const last=lastSetFor(ex.id);if(!last)return true;const today=new Date(),cutoff=new Date(today.getFullYear(),today.getMonth(),today.getDate()-14);return last.date<localDateKey(cutoff);}).length;}
function renderExerciseResults(){const el=document.getElementById('exercise-results');if(!el)return;const arr=filteredExerciseList(),favCount=state.favorites?.exercises?.length||0,prCount=exercises.filter(ex=>!!bestSetFor(ex.id)).length,noneCount=exercises.filter(ex=>ex.equip==='none').length,begCount=exercises.filter(ex=>ex.level==='beginner').length,favBtn=favCount||state.exerciseFilters.favOnly?`<button type="button" class="btn btn-small" data-action="toggle-ex-fav" aria-pressed="${state.exerciseFilters.favOnly?'true':'false'}">♥ ${textFor('favorites.only','Само любими')}${favCount?' ('+favCount+')':''}</button>`:'',prBtn=prCount||state.exerciseFilters.prOnly?`<button type="button" class="btn btn-small" data-action="toggle-ex-pr" aria-pressed="${state.exerciseFilters.prOnly?'true':'false'}">★ ${textFor('progress.recordsTitle','Лични рекорди')}${prCount?' ('+prCount+')':''}</button>`:'',noneBtn=`<button type="button" class="btn btn-small" data-action="toggle-ex-none" aria-pressed="${state.exerciseFilters.equip==='none'?'true':'false'}">${textFor('equipment.none','Без оборудване')} (${noneCount})</button>`,begBtn=`<button type="button" class="btn btn-small" data-action="toggle-ex-beginner" aria-pressed="${state.exerciseFilters.level==='beginner'?'true':'false'}">${textFor('level.beginner','Начинаещ')} (${begCount})</button>`,staleCount=excStaleCount(),staleBtn=`<button type="button" class="btn btn-small" data-action="toggle-ex-stale" aria-pressed="${state.exerciseFilters.staleOnly?'true':'false'}">${esc(textFor('exercises.stale','Не са тренирани от 14 дни'))} (${staleCount})</button>`;el.innerHTML=resultsHead('exercises',arr.length,textFor('common.found','Намерени '+arr.length+' от '+exercises.length+' упражнения',{found:arr.length,total:exercises.length}),favBtn+prBtn+noneBtn+begBtn+staleBtn)+(arr.length?`<div class="grid-3">${arr.map(exerciseCard).join('')}</div>`:emptyResults('exercises'));}
