function renderPage(){
 const active=app.contains?.(document.activeElement)?document.activeElement:null;
 const action=active?.dataset.action;
 const activeId=active?.id;
 const identity=Object.fromEntries(['id','tab','view','kind','day','date','index'].filter(key=>active?.dataset[key]!==undefined).map(key=>[key,active.dataset[key]]));
 if(!nav.some(x=>x[0]===state.page))state.page='home';
 refreshNav();
 app.innerHTML=({home,sessions:sessionsPage,exercises:exercisesPage,nutrition:nutritionPage,plan:planPage,progress:progressPage,favorites:favoritesPage}[state.page])();
 if(state.page==='nutrition'&&state.foodTab==='meal'){const mealNameInput=document.getElementById('meal-name'),mealDateInput=document.getElementById('meal-date');if(mealNameInput)mealNameInput.value=state.mealName;if(mealDateInput)mealDateInput.value=state.mealDate;}
 renderWorkoutResults();renderExerciseResults();renderFoodResults();
 if(action){
  const altAction=({'today-completion-add':'today-completion-remove','today-completion-remove':'today-completion-add'})[action];
  const replacement=Array.from(app.querySelectorAll('[data-action]')).find(el=>(el.dataset.action===action||el.dataset.action===altAction)&&Object.entries(identity).every(([key,value])=>el.dataset[key]===value));
  if(replacement&&!replacement.disabled)replacement.focus();
 }else if(activeId){const replacement=document.getElementById(activeId);if(app.contains?.(replacement))replacement.focus();}
}
function focusPageHeading(){app.querySelector?.('.page-heading h2, .hero h1')?.focus?.({preventScroll:true});}
function focusFoodTab(tab){app.querySelector?.(`[data-action="food-tab"][data-tab="${tab}"]`)?.focus?.();}
function openModal(html,label,keepFocus=false){if(!modalRoot.innerHTML)modalTrigger=document.activeElement;modalRoot.innerHTML=`<div class="modal-overlay" data-action="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(label||textFor('common.details','Детайли'))}"><button class="modal-close" data-action="close-modal" aria-label="${textFor('common.close','Затвори')}">×</button>${html}</section></div>`;document.body.style.overflow='hidden';if(!keepFocus)modalRoot.querySelector('.modal-close')?.focus?.();}
function closeModal(){const refresh=!!state.player?.saved,trigger=modalTrigger,action=trigger?.dataset?.action,id=trigger?.dataset?.id,domId=trigger?.id;if(state.player){state.player=null;clearInterval(playerInterval);playerInterval=null;syncWakeLock();}state.openDetail=null;modalRoot.innerHTML='';document.body.style.overflow='';modalTrigger=null;if(refresh)renderPage();if(trigger?.isConnected!==false)trigger?.focus?.();else if(action)app.querySelector?.(`[data-action="${action}"]${id?`[data-id="${id}"]`:''}`)?.focus?.();else if(domId)document.getElementById(domId)?.focus?.();}
