function nutritionTable(f,grams){const v=C.calculateForGrams(f,grams),goal=typeof nutritionJournal!=='undefined'?nutritionJournal?.day(localDateKey(new Date()))?.goal:null,shares=C.macroCalorieShares?C.macroCalorieShares(v):null,goalInfo=goal&&v.kcal>0?`${Math.round(v.kcal/Math.max(1,goal.kcal)*100)}% kcal${goal.protein>0?' · '+Math.round(v.protein/goal.protein*100)+'% '+textFor('nutrition.protein','Протеин').toLowerCase():''}${v.fiber>0?' · '+Math.round(v.fiber/25*100)+'% '+textFor('nutrition.fibre','фибри').toLowerCase():''}`:'',splitInfo=shares&&(shares.proteinPct+shares.carbsPct+shares.fatPct)>0?`${textFor('nutrition.protein','Протеин')} ${shares.proteinPct}% · ${textFor('nutrition.carbs','Въглехидрати')} ${shares.carbsPct}% · ${textFor('nutrition.fat','Мазнини')} ${shares.fatPct}%`:'';return `<table class="nutri-table"><thead><tr><th>${textFor('nutrition.value','Хранителна стойност')}</th><th>${textFor('nutrition.perHundred','100 г')}</th><th>${fmt(grams)} ${textFor('nutrition.gramsUnit','г')}</th></tr></thead><tbody>${[[textFor('nutrition.energy','Енергия'),'kcal','kcal'],[textFor('nutrition.protein','Протеин'),'protein','г'],[textFor('nutrition.carbs','Въглехидрати'),'carbs','г'],[textFor('nutrition.fat','Мазнини'),'fat','г'],[textFor('nutrition.fibre','Фибри'),'fiber','г']].map(([name,key,unit])=>`<tr><td>${name}</td><td>${fmt(f[key])} ${unit==='г'?textFor('nutrition.gramsUnit','г'):unit}</td><td>${fmt(v[key])} ${unit==='г'?textFor('nutrition.gramsUnit','г'):unit}</td></tr>`).join('')}</tbody></table>${goalInfo||splitInfo?`<p class="subtle detail-macro-summary">${[goalInfo,splitInfo].filter(Boolean).join(' · ')}</p>`:''}`;}
