function addFood(id,grams='100'){if(!byId(foods,id))return false;const updated=[...state.meal,{id,grams}];if(!save('current-meal',updated))return false;state.meal=updated;toast(textFor('nutrition.addedMessage','Продуктът е добавен към храненето.'));if(state.page==='nutrition'&&state.foodTab==='meal')renderPage();return true;}
function beep(){if(!state.sound)return;try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;audioCtx=audioCtx||new AudioContext();if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=740;g.gain.setValueAtTime(.0001,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.08,audioCtx.currentTime+.02);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.18);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.2);}catch{}}
function startWorkout(id){const w=byId(workouts,id);if(!w)return;state.openDetail=null;announcePlayer.last=null;state.player={w,rounds:w.rounds,steps:Array.from({length:w.rounds},()=>w.ids).flat(),index:0,phase:'ready',running:false,started:false,saved:false,remainingMs:w.workSec*1000,endAt:null,workMs:w.workSec*1000,restMs:w.restSec*1000,startedAt:null,pausedAt:null,pausedMs:0,finishedAt:null};openModal(`<div class="player-layout" id="player-layout"></div><p class="sr-only" id="player-announcer" role="status" aria-live="assertive"></p>`,contentFor('workout',w).name);modalRoot.querySelector('.modal').classList.add('player-modal');renderPlayer();clearInterval(playerInterval);playerInterval=setInterval(tickPlayer,200);}
function currentExercise(){const p=state.player;return p?byId(exercises,p.steps[p.index]):null;}
function savePlayerResult(){const p=state.player;if(!p||p.phase!=='done'||p.saved)return;const pausedAtFinish=p.pausedAt===null?0:Math.max(0,p.finishedAt-p.pausedAt);const minutes=Math.max(0,(p.finishedAt-p.startedAt-p.pausedMs-pausedAtFinish)/60000);p.saved=!!journal?.recordWorkout(p.w.id,localDateKey(new Date()),minutes);if(!p.saved&&journal)toast(textFor('progress.saveFailed','Неуспешно запазване на тренировката.'));}
function transitionPlayer(overflow=0,manual=false){const p=state.player;if(!p)return;beep();if(p.phase==='work'){if(p.index===p.steps.length-1){p.finishedAt=manual?Date.now():p.endAt;p.phase='done';p.running=false;p.remainingMs=0;syncWakeLock();savePlayerResult();return;}p.phase='rest';p.remainingMs=p.restMs;}else if(p.phase==='rest'){p.index++;p.phase='work';p.remainingMs=p.workMs;}if(p.running)p.endAt=Date.now()+p.remainingMs-overflow;}
function tickPlayer(){const p=state.player;if(!p||!p.running)return;let now=Date.now(),guard=0;while(p.running&&now>=p.endAt&&guard++<100){const overflow=now-p.endAt;transitionPlayer(overflow);if(p.phase==='done')break;}if(p.running)p.remainingMs=Math.max(0,p.endAt-now);updatePlayerClock();if(guard>0)renderPlayer();}
function playerControl(action){const p=state.player;if(!p)return;if((action==='player-pause'||action==='player-next'||action==='player-prev'||action==='player-add-time'||action==='player-sub-time'||action==='player-skip-rest')&&p.running)tickPlayer();if(action==='player-start'&&p.phase==='ready'){p.phase='work';p.started=true;p.running=true;p.startedAt=Date.now();p.endAt=p.startedAt+p.remainingMs;beep();}else if(action==='player-pause'&&p.running){p.remainingMs=Math.max(0,p.endAt-Date.now());p.running=false;p.pausedAt=Date.now();}else if(action==='player-resume'&&p.started&&!p.running&&p.phase!=='done'){p.pausedMs+=Math.max(0,Date.now()-p.pausedAt);p.pausedAt=null;p.running=true;p.endAt=Date.now()+p.remainingMs;}else if(action==='player-add-time'&&p.started&&p.phase!=='done'){p.remainingMs=Math.min(600000,p.remainingMs+15000);if(p.running)p.endAt=Date.now()+p.remainingMs;}else if(action==='player-sub-time'&&p.started&&p.phase!=='done'){p.remainingMs=Math.max(1000,p.remainingMs-15000);if(p.running)p.endAt=Date.now()+p.remainingMs;}else if(action==='player-prev'&&p.started&&p.phase!=='done'&&(p.phase==='rest'||p.index>0)){if(p.phase==='rest'){p.phase='work';p.remainingMs=p.workMs;}else{p.index--;p.phase='work';p.remainingMs=p.workMs;}if(p.running)p.endAt=Date.now()+p.remainingMs;beep();}else if(action==='player-next'&&p.started&&p.phase!=='done'){const wasRunning=p.running;transitionPlayer(0,true);p.running=wasRunning&&p.phase!=='done';if(p.running)p.endAt=Date.now()+p.remainingMs;}else if(action==='player-skip-rest'&&p.phase==='rest'){const wasRunning=p.running;transitionPlayer(0,true);p.running=wasRunning&&p.phase!=='done';if(p.running)p.endAt=Date.now()+p.remainingMs;}else if(action==='player-restart'){p.index=0;p.phase='ready';p.running=false;p.started=false;p.saved=false;p.remainingMs=p.workMs;p.startedAt=null;p.pausedAt=null;p.pausedMs=0;p.finishedAt=null;}else if(action==='player-save'){savePlayerResult();}syncWakeLock();renderPlayer();}
function totalRemainingMs(p){if(!p||p.phase==='done')return 0;const rem=Math.max(0,p.steps.length-1-p.index);return p.phase==='rest'?p.remainingMs+rem*p.workMs+Math.max(0,rem-1)*p.restMs:p.remainingMs+rem*(p.restMs+p.workMs);}
