function updatePlayerClock(){const el=document.getElementById('player-clock'),tot=document.getElementById('player-total-remaining');if(el&&state.player)el.textContent=C.formatClock(state.player.remainingMs);if(tot&&state.player)tot.textContent=C.formatClock(totalRemainingMs(state.player));}
/* Screen readers get one short message per phase change instead of a silent redraw. */
function announcePlayer(){
 const p=state.player,el=document.getElementById('player-announcer');
 if(!p||!el)return;
 const e=contentFor('exercise',byId(exercises,p.steps[p.index]))||{},next=contentFor('exercise',byId(exercises,p.steps[p.index+1]))||{};
 const key=p.phase+'|'+p.index;
 if(announcePlayer.last===key)return;
 announcePlayer.last=key;
 el.textContent=p.phase==='done'?textFor('timer.done','ГОТОВО')+'. '+(p.saved?textFor('progress.workoutSaved','Тренировката е записана в дневника.'):textFor('timer.completedInfo','Завърши заниманието. Няма автоматично записване в дневник.'))
  :p.phase==='rest'?textFor('timer.announceRest','Почивка. Следва: '+(next.name||textFor('timer.finish','Финал')),{exercise:next.name||textFor('timer.finish','Финал')})
  :p.phase==='ready'?textFor('timer.ready','ГОТОВ ЛИ СИ?')+' '+(e.name||'')
  :textFor('timer.announceWork','Работа: '+(e.name||''),{exercise:e.name||''});
}
